/**
 * vips_vipsload:
 * @filename: file to load
 * @out: (out): decompressed image
 * @...: %NULL-terminated list of optional named arguments
 *
 * Read in a vips image.
 *
 * See also: vips_vipssave().
 *
 * Returns: 0 on success, -1 on error.
 */
int
vips_vipsload( const char *filename, VipsImage **out, ... )
{
        va_list ap;
        int result;

        va_start( ap, out );
        result = vips_call_split( "vipsload", ap, filename, out );
        va_end( ap );

        return( result );
}

vips__file_magic( const char *filename )
{
        guint32 magic;

        if( vips__get_bytes( filename, (unsigned char *) &magic, 4 ) == 4 &&
                (magic == VIPS_MAGIC_INTEL ||
                 magic == VIPS_MAGIC_SPARC) )
                return( magic );

        return( 0 );
}

